"""Full dependency/generated bytes, not selected JS files alone, are frozen."""
from pathlib import Path
import sys
import tempfile
import unittest
from unittest.mock import patch
sys.path.insert(0, str(Path(__file__).resolve().parents[2] / 'scripts'))
import convex_profile as profile


class FullConvexFreeze(unittest.TestCase):
    def test_every_dependency_generated_file_and_added_file_changes_digest(self):
        self.assertTrue(callable(getattr(profile, 'tree_inventory', None)), 'Full runtime/dependency inventory missing')
        with tempfile.TemporaryDirectory() as directory:
            root=Path(directory)
            for name in ['node_modules/convex/dist/deep.js', 'convex/_generated/server.js']:
                p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(b'original')
            before=profile.tree_inventory(root)
            for name in ['node_modules/convex/dist/deep.js', 'convex/_generated/server.js']:
                p=root/name;p.write_bytes(b'changed');self.assertNotEqual(profile.tree_inventory(root),before);p.write_bytes(b'original')
            (root/'node_modules/added').write_bytes(b'new');self.assertNotEqual(profile.tree_inventory(root),before)

    def test_symlinks_are_preserved_in_inventory_and_escape_refused(self):
        self.assertTrue(callable(getattr(profile, 'tree_inventory', None)), 'Full runtime/dependency inventory missing')
        with tempfile.TemporaryDirectory() as directory:
            root=Path(directory);(root/'target').write_bytes(b'one');(root/'link').symlink_to('target')
            rows=profile.tree_inventory(root);self.assertTrue(any(row.get('link')=='target' for row in rows))
            (root/'link').unlink();(root/'link').symlink_to('/etc/passwd')
            with self.assertRaises(RuntimeError):profile.tree_inventory(root)

    def test_missing_required_dependency_or_generated_tree_is_refused(self):
        self.assertTrue(callable(getattr(profile, 'full_runtime_state', None)), 'Complete installed runtime/generated gate missing')
        with tempfile.TemporaryDirectory() as directory, patch.object(profile, 'ROOT', Path(directory)):
            with self.assertRaises(RuntimeError):profile.full_runtime_state()


if __name__=='__main__':unittest.main(verbosity=2)
